describe('Currency Field Formatting', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="currency-input"]').as('currencyInput');
    cy.get('[data-testid="currency-display"]').as('currencyDisplay');
  });

  it('should format currency with commas and two decimal places on valid input', () => {
    cy.get('@currencyInput').type('1234567.89');
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '$1,234,567.89');
    cy.get('@currencyInput').should('have.value', '1234567.89');
  });

  it('should format currency with commas and two decimal places when input lacks decimals', () => {
    cy.get('@currencyInput').type('5000');
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '$5,000.00');
  });

  it('should handle single decimal place and pad with zero', () => {
    cy.get('@currencyInput').type('999.5');
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '$999.50');
  });

  it('should format large numbers with multiple comma separators', () => {
    cy.get('@currencyInput').type('123456789.99');
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '$123,456,789.99');
  });

  it('should handle zero value correctly', () => {
    cy.get('@currencyInput').type('0');
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '$0.00');
  });

  it('should reject non-numeric characters except decimal point', () => {
    cy.get('@currencyInput').type('abc123');
    cy.get('@currencyInput').should('have.value', '123');
  });

  it('should handle multiple decimal points by keeping only first one', () => {
    cy.get('@currencyInput').type('100.50.25');
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '$100.50');
  });

  it('should trim excess decimal places beyond two', () => {
    cy.get('@currencyInput').type('99.999');
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '$99.99');
  });

  it('should handle negative currency values with proper formatting', () => {
    cy.get('@currencyInput').type('-5000.50');
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '-$5,000.50');
  });

  it('should clear formatting when input is cleared', () => {
    cy.get('@currencyInput').type('1000.00');
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '$1,000.00');
    cy.get('@currencyInput').clear();
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '');
  });

  it('should maintain formatting on form submission', () => {
    cy.get('@currencyInput').type('2500.75');
    cy.get('@currencyInput').blur();
    cy.get('[data-testid="submit-button"]').click();
    cy.get('[data-testid="form-success"]').should('be.visible');
    cy.get('[data-testid="submitted-value"]').should('have.text', '2500.75');
  });

  it('should handle paste events with unformatted currency', () => {
    cy.get('@currencyInput').invoke('val', '1234567.89').trigger('change');
    cy.get('@currencyInput').blur();
    cy.get('@currencyDisplay').should('have.text', '$1,234,567.89');
  });

  it('should validate minimum and maximum currency amounts', () => {
    cy.get('@currencyInput').type('0.01');
    cy.get('@currencyInput').blur();
    cy.get('[data-testid="validation-error"]').should('not.exist');
    cy.get('@currencyInput').clear().type('999999999.99');
    cy.get('@currencyInput').blur();
    cy.get('[data-testid="validation-error"]').should('not.exist');
  });
});
